from taf.internal.managedobject import ManagedObject
from ...collector_configuration_data import CollectorConfigurationData


class Builder(ManagedObject):
    def __init__(self, ne_id, **kwargs):
        super().__init__(**kwargs)
        self.ne_id = ne_id
        self._collector_configuration_data = CollectorConfigurationData()

    def get_result(self):
        return self._collector_configuration_data

    def add_group(self, ne_log_name, ne_log_configuration):
        self._collector_configuration_data.append(
            {
                'name': ne_log_name,
                'type': "group",
                'members': ne_log_configuration["members"].copy()})
